function statsAt(){const f=Math.min(state.time,surface.duration)/surface.step,a=Math.floor(f),b=Math.min(a+1,surface.stats.length-1),u=f-a;let s={};for(const k of ['area','volume','maxDepth','inletStage','outletStage','maxSpeed','rainWetArea','rainMaxDepth'])s[k]=surface.stats[a][k]*(1-u)+surface.stats[b][k]*u;return s}
function makeObjects(){
 for(const n of data.nodes)objects[n.id]={...n,kind:'node',name:'管网节点'};
 data.geography.buildings.forEach((b,index)=>{const id='B'+String(index).padStart(4,'0');objects[id]={id,name:`${b.floors} 层 · ${b.roofType==='pitched'?'坡屋顶':'平屋顶'}`,xy:b.xy,ground:b.ground,kind:'building',sourceIndex:index,sourceId:b.id,floors:b.floors,height:b.height,roofRise:b.roofRise}});
 for(const s of data.sensors.filter(x=>x.visible))objects[s.id]={...s,kind:'sensor',name:names[s.id]||'源监测点'};
 const checkpoints=[['P01','坡面检查点',[-200,450]],['P02','洼地检查点',[-79.167,837.5]],['P03','边界检查点',[795.833,162.5]]];
 for(const [id,name,xy] of checkpoints){const i=scene.nearestCell(...xy);objects[id]={id,name,xy,cell:i,ground:scene.height(...xy),kind:'checkpoint'}}
 if(emergency){objects['R01']={id:'R01',name:'巡查组 · R-01',xy:emergency.route[0],kind:'resource'};objects['C01']={id:'C01',name:'道路检查点 · C-01',xy:emergency.checkpoint,kind:'resource'};objects['S01']={id:'S01',name:'假设集结点 · S-01',xy:emergency.route[0],kind:'resource'};scene.addRoute(emergency.route)}
 for(const obj of Object.values(objects).filter(o=>['sensor','checkpoint','resource'].includes(o.kind)))scene.addMarker(obj.id,obj.xy,obj.kind);
}
function selected(){return objects[state.selected]||objects.P02}
function seriesAtObject(obj=selected()){
 if(!networkEvidence()||!['sensor','node'].includes(obj.kind)){if(obj.kind==='resource')return scene.depthSeries(obj.xy);if(obj.track)return obj.depthSeries||(obj.depthSeries=Array.from({length:surface.grid.frames},(_,f)=>({t:f*surface.step,value:scene.field.sampleFrame(...sampleTrack(obj.track,f*surface.step).xy,f)?.depth})));return obj.depthSeries||(obj.depthSeries=obj.kind==='building'?scene.buildingSeries(obj.sourceIndex):scene.depthSeries(obj.xy))}
 return history.sensors[obj.id]?.model||[];
}
function observation(obj=selected()){const channels=history.sensors[obj.id]?.observations||[];if(!channels.length)return[];return (channels.find(c=>c.name.includes(obj.id==='G71F05R'?'LevelBasin':obj.id==='G71F06R'?'LevelInlet':obj.id==='G71F68Y'?'LevelPS':'Level1'))||channels[0]).series}
function qualityAt(){const obs=observation();const row=[...obs].reverse().find(p=>p.t<=state.time);return !row||row.value==null?'缺测 / 无有效观测':row.flags?.length?row.flags.join(', '):'无源异常标记'}
function buildingInspector(o){
 const r=scene.buildingReading(o.sourceIndex),roof=o.ground+o.height+o.roofRise;
 return `<section class="side-section building-inspector"><div class="section-title"><h2>建筑淹没判读</h2><span class="tag orange">示意楼层</span></div><div class="inspector-head"><span class="inspector-icon">${ico('Building2')}</span><div><h3>${o.id}</h3><p>真实轮廓 · ${o.name}</p></div></div><div class="inspect-reading"><strong class="mono" id="building-depth">${fmt(r.depth)}<small>m</small></strong><span class="tag blue" id="building-status">${r.status}</span></div><div class="floor-diagram"><div class="roof-indicator">示意层顶 / 屋顶 <span class="mono">${fmt(roof,1)} m</span></div>${Array.from({length:o.floors},(_,i)=>o.floors-i).map(f=>`<div class="floor-row ${r.depth>(f-1)*2.9+.15?'underwater':''}" data-floor="${f}" style="--wet:${Math.max(0,Math.min(1,(r.depth-(f-1)*2.9)/2.9))*100}%"><span>${f}F</span><i></i><i></i><span>${fmt(o.ground+f*2.9,1)} m</span></div>`).join('')}</div><dl><div><dt>建筑边缘模型水位</dt><dd class="mono" id="building-stage">${fmt(r.stage)} m DVR90</dd></div><div><dt>示意地坪</dt><dd class="mono">${fmt(o.ground)} m DVR90</dd></div><div><dt>楼层依据</dt><dd>${o.floors} 层 × 2.9 m · 假设</dd></div><div><dt>源轮廓 ID</dt><dd class="mono">${o.sourceId}</dd></div></dl><div class="note-box">以建筑边缘求解水位与示意楼层标高对照。水深为模拟，楼层为示意；不等同于真实灾损调查。</div><button class="focus-btn" id="focus-selected">${ico('Focus')}街区近景定位</button></section>`;
}
function updateBuildingReadings(){
 const o=selected();if(o.kind!=='building'||!$('#building-depth'))return;const r=scene.buildingReading(o.sourceIndex);
 $('#building-depth').innerHTML=`${fmt(r.depth)}<small>m</small>`;$('#building-status').textContent=r.status;$('#building-stage').textContent=`${fmt(r.stage)} m DVR90`;$$('[data-floor]').forEach(el=>{el.classList.toggle('underwater',r.depth>(+el.dataset.floor-1)*2.9+.15);el.style.setProperty('--wet',Math.max(0,Math.min(1,(r.depth-(+el.dataset.floor-1)*2.9)/2.9))*100+'%')});
}
function inspector(){
 const o=selected(),series=seriesAtObject(o),val=at(series,state.time),obs=(!networkEvidence()||!['sensor','node'].includes(o.kind))?null:at(observation(o),state.time),inside=scene.nearestCell(...o.xy)>=0;
 if(o.kind==='assembly')return assemblyInspector(o,currentAssemblies().find(a=>a.id===o.id),scene,ico);
 if(['evacuee','patrol'].includes(o.kind))return operationInspector(o,plans[state.scenario],currentOps(),scene,ico);
 if(o.kind==='resource')return resourceInspector(o);if(o.kind==='building')return buildingInspector(o);
 return `<section class="side-section"><div class="section-title"><h2>对象检查</h2><span class="tag ${(!networkEvidence()||!['sensor','node'].includes(o.kind))?'orange':'blue'}">${(!networkEvidence()||!['sensor','node'].includes(o.kind))?'模型采样':'实测 / 模型'}</span></div><div class="inspector-head"><span class="inspector-icon">${ico(o.kind==='node'?'GitBranch':'MapPin')}</span><div><h3>${o.id}</h3><p>${o.name}</p></div></div><div class="inspect-reading"><strong class="mono" id="object-reading">${fmt(val)}<small>m</small></strong><span class="tag gray">${(!networkEvidence()||!['sensor','node'].includes(o.kind))?'地表水深':'管网水头'}</span></div><dl><div><dt>数据类型</dt><dd>${(!networkEvidence()||!['sensor','node'].includes(o.kind))?'ANUGA 地表情景':'SWMM 模型 · 未率定'}</dd></div>${!(!networkEvidence()||!['sensor','node'].includes(o.kind))?`<div><dt>实测水位</dt><dd class="mono" id="observed-reading">${fmt(obs)} m DVR90</dd></div>`:''}<div><dt>地面高程</dt><dd class="mono">${fmt(o.ground)} m DVR90</dd></div><div><dt>${(!networkEvidence()||!['sensor','node'].includes(o.kind))?'计算域':'节点映射'}</dt><dd>${(!networkEvidence()||!['sensor','node'].includes(o.kind))?(inside?'域内 · 连续场采样':'域外 · 无地表结果'):(history.sensors[o.id]?.modelNode||'无对应结果')}</dd></div><div><dt>质量 / 局限</dt><dd>${(!networkEvidence()||!['sensor','node'].includes(o.kind))?`${surface.assumptions.mesh_spacing_m} m 网格 · 假设边界`:`<span id="quality-reading">${qualityAt()}</span>`}</dd></div></dl><div class="quality-line">${ico('Info')} ${(!networkEvidence()||!['sensor','node'].includes(o.kind))?'源监测点位置不代表此情景存在实测。':'实测与模型使用各自高程；无自动校准。'}</div><button class="focus-btn" id="focus-selected">${ico('Focus')}定位到此对象</button></section>`;
}
function layerSection(){
 const rows=[['rain','降雨视觉','#bdd6da','密度限幅'],['terrain','真实地形','#b6bf9b','DVR90'],['buildings','楼层 / 屋顶','#9aa58e','示意层高'],['roads','道路 / 示意车辆','#acb7b2','源中心线'],['rivers','河道与湖泊','#86aca2','源矢量'],['flood','连续洪水表面','#378b9b','水深'],['flow','水流粒子示踪','#b9dfe1','×8视觉'],['vectors','速度方向箭头','#b8cdca','m/s'],['network','排水管网','#5d9180','独立'],['sensors','空间标签 / 检查点','#c5ab77','对象'],['domain','计算域边界','#b4c6a6','范围']];
 return `<section class="side-section"><div class="section-title"><h2>场景图层</h2><small>水深与流场分开控制</small></div>${rows.map(([id,n,c,meta])=>`<label class="layer-row"><input type="checkbox" data-layer="${id}" ${state.layers[id]?'checked':''} ><span class="swatch" style="background:${c}"></span><span class="layer-name">${n}</span>${['flood','network','rain'].includes(id)?`<input type="range" data-opacity="${id}" min="10" max="100" value="${state.opacities[id]*100}" aria-label="${n}透明度">`:`<small>${meta}</small>`}</label>`).join('')}<div class="flow-controls"><label>示踪密度预算 <span class="mono" id="density-value">${state.particleDensity}</span><input id="particle-density" type="range" min="400" max="2400" step="100" value="${state.particleDensity}" aria-label="流场粒子密度"></label><p>城市粒子按当前速度场平流，密度随远近调节；×8 为视觉时间倍率；不代表真实漂浮物。</p></div></section>`;
}
function overview(){const q=statsAt();return `<section class="side-section"><div class="eyebrow">${isSurface()?'COMPOUND RAIN + RIVER':'OBSERVED RAIN → MODEL SURFACE'}</div><h2 class="scenario-name">${isSurface()?'假设外洪与降雨':'历史降雨积水试算'}</h2><span class="tag ${isSurface()?'orange':'blue'}">${isSurface()?'假设情景':'雨量实测'}</span> <span class="tag">水深模拟 · 未率定</span><p class="description">${isSurface()?'假设河道涨水 + 36.46 mm假设降雨。':'2012-06-29 · rg5425 · 19.40 mm。<br>rg5427单独对照，不混入地表输入。'}</p><div class="metric-grid"><div><span class="label">${isSurface()?'湿面积 · 含河道':'初始干区新增湿面积'}</span><strong id="area-metric">${fmt((isSurface()?q.area:q.rainWetArea)/10000,1)}<small>ha</small></strong></div><div><span class="label">${isSurface()?'最大水深':'初始干区最大水深'}</span><strong id="depth-metric">${fmt(isSurface()?q.maxDepth:q.rainMaxDepth)}<small>m</small></strong></div></div><div class="note-box">${surface.nativeCells.toLocaleString()} 单元 / ${surface.assumptions.mesh_spacing_m} m 网格。${isSurface()?'非历史灾害重建。':'历史积水为新试算，初始河道与边界是假设。'}无入渗、无排水，未与SWMM耦合。</div></section>`}
function objectsSection(){
 const ids=state.workspace==='response'?['R01','C01','S01']:state.workspace==='monitor'?['G71F04R','G71F05R','G71F06R','G71F68Y','G73F010','G72F040']:[...(surface.showcaseBuildings||[]),...(!isSurface()?['P04']:[]),'P01','P02','P03','G71F04R','G71F05R'];
 return `<section class="side-section"><div class="section-title"><h2>${state.workspace==='response'?'情景资源':'检查点与监测位置'}</h2><small>${ids.length} 个对象</small></div><div class="object-list" data-scroll-key="objects">${ids.filter(id=>objects[id]).map(id=>{const o=objects[id],v=at(seriesAtObject(o),state.time);return `<button class="object-row ${id===state.selected?'active':''}" data-object="${id}"><span class="obj-icon">${ico(o.kind==='resource'?'Truck':'MapPin')}</span><span class="obj-text"><b>${id} ${o.kind==='checkpoint'?o.name:''}</b><small>${o.kind==='resource'?o.name:o.name||'源传感器位置'}</small></span><span class="reading mono" data-row-reading="${id}">${o.kind==='resource'?'›':fmt(v)}<small>${o.kind==='resource'?'':' m'}</small></span></button>`}).join('')}</div>${state.workspace==='monitor'&&isSurface()?'<div class="note-box orange">当前为假设地表情景，无匹配实测。切换历史窗口可查看真实水位与独立管网结果。</div><button class="focus-btn" id="show-history">查看 2012 历史监测窗口 →</button>':''}</section>`;
}
function eventsSection(){const events=isSurface()?surfaceEvents:historyEvents;return `<section class="side-section"><div class="section-title"><h2>关键事件</h2><small>点击定位时间</small></div><div class="events">${events.map((e,i)=>`<button class="event-row ${state.time>=e.t&&(i===events.length-1||state.time<events[i+1].t)?'active':''}" data-event="${e.t}" title="${e.note}"><span class="event-dot"></span><span class="event-text">${e.name}</span><time class="mono">${isSurface()?clock(e.t):clock(e.t+16200)}</time></button>`).join('')}</div></section>`}
function sources(){return `<section class="side-section"><div class="section-title"><h2>来源与模型边界</h2><small>v0.4</small></div><div class="source-card"><span class="tag blue">真实空间资料</span><h3>DTU / VCS · Bellinge</h3><p>原生0.4 m地形、建筑轮廓、道路与水系。EPSG:25832 / DVR90。源矢量2019年导出；楼层、屋顶、植被和车辆为示意。</p><a href="https://doi.org/10.11583/DTU.c.5029124" target="_blank" rel="noreferrer">数据集 DOI ↗</a></div><div class="source-card"><span class="tag blue">按站点分离的实测雨量</span><h3>rg5425 / rg5427</h3><p>地表历史输入rg5425：19.40046 mm、最高108 mm/h（分钟平均）；rg5427：23.60064 mm，独立保留为对照。没有叠加两个站点。事件文件省略的分钟按干时段处理，分钟体积解释为该时间戳之后60秒的雨量。</p></div><div class="source-card"><span class="tag orange">独立地表模型</span><h3>ANUGA · 精确积分降雨源项</h3><p>复合情景102,400单元/10 m，假设雨量36.46 mm；历史试算40,000单元/16 m。降雨已进入计算，展示采样8 m。无入渗、无排水，未与SWMM交换水量。</p><p>历史河道初始13.8 m及入口13.8 / 出口13.2 m DVR90为假设常水位；复合情景峰值入口27 / 出口23 m也是假设。建筑为有限示意高度的等效阻水体；桥涵、窄巷和门窗未解析，没有已验证历史淹水精度。</p></div><div class="source-card"><span class="tag">疏散与安全</span><h3>示意规则，非官方安全标准</h3><p>绿色：未来30分钟+分钟分档缓冲内，水深&lt;0.08 m、流速&lt;0.25 m/s，90 m内有干道路连接集结点；红色：水深≥0.30 m，或水深&gt;0.05 m且流速≥1 m/s / 深速乘积≥0.15 m²/s。黄色待核查，灰色未评估。室内、域外和无连通资料不视为安全。</p><p>360人为18个示意队列。集结点与容量均假设，沿源道路按到达时刻检查水情、必要时重规划或受阻待援。巡检3队6人沿整个窗口干燥道路往返、检查与集结点引导，没有真实人员轨迹。</p></div><div class="source-card"><span class="tag blue">历史监测 / 独立管网</span><h3>实测 level / SWMM head</h3><p>源质量标记保留。SWMM冷启动、未率定，与ANUGA独立进程运行。管网水头不是地表水深。雨量分包CC BY-NC 4.0，保留原分包许可。</p></div><div class="note-box">雨滴和流场粒子可以在暂停时继续视觉相位；水情、累计雨量、人员、容量及任务均由物理时间确定。安全分区、人口和任务为研究演示。</div></section>`}
function routeStatus(){
 if(!emergency)return{progress:0,xy:[0,0],status:'未生成',distance:0};
 const f=Math.min(60,state.time/120),a=Math.floor(f),b=Math.min(60,a+1),u=f-a,terminal=emergency.frames.at(-1),departure=emergency.assumptions.departure_s,speed=emergency.assumptions.speed_kmh*1000/3600,distance=Math.min(terminal.distance,Math.max(0,(state.time-departure)*speed)),index=Math.min(emergency.route.length-2,Math.floor(distance/10)),fraction=Math.min(1,Math.max(0,(distance-index*10)/(index===emergency.route.length-2?emergency.length_m-index*10:10))),p=emergency.route[index],q=emergency.route[index+1],xy=[p[0]+(q[0]-p[0])*fraction,p[1]+(q[1]-p[1])*fraction];
 return {...emergency.frames[a],distance,xy,status:state.time<departure?'待出发':distance>=terminal.distance?(emergency.frames[a].status==='沿线巡查'?emergency.frames[b].status:emergency.frames[a].status):'沿线巡查',maxDepth:emergency.frames[a].maxDepth*(1-u)+emergency.frames[b].maxDepth*u};
}
function resourceInspector(o){const s=routeStatus();return `<section class="side-section"><div class="section-title"><h2>假设资源详情</h2><span class="tag orange">情景设定</span></div><div class="inspector-head"><span class="inspector-icon">${ico(o.id==='R01'?'Truck':o.id==='C01'?'ShieldCheck':'MapPin')}</span><div><h3>${o.name}</h3><p>非真实救援调度或人员轨迹</p></div></div><div class="inspect-reading"><strong class="mono" id="resource-reading">${o.id==='R01'?fmt(s.distance/1000,2):o.id==='C01'?'0.30':'—'}<small>${o.id==='R01'?'km':o.id==='C01'?'m 阈值':''}</small></strong><span class="tag orange">${o.id==='R01'?s.status:o.id==='C01'?'检查规则':'候选集结'}</span></div><dl><div><dt>任务</dt><dd>${o.id==='R01'?'道路巡查 · 候选路径':o.id==='C01'?'检查模型道路水深':'情景集结 · 容量未知'}</dd></div><div><dt>计划出发</dt><dd>T + 00:20</dd></div><div><dt>道路路径</dt><dd>${fmt(emergency?.length_m/1000,2)} km · 源中心线</dd></div><div><dt>假设行驶速度</dt><dd>8 km/h · 遇水深 ≥ 0.30 m 停止</dd></div></dl><button class="focus-btn" id="focus-selected">${ico('Focus')}定位资源</button><div class="note-box orange">按沿途到达时刻采样模型水深，触及阈值停止。路径拓扑仅作演示；不构成通行或安全建议。</div></section>`}
function responseOverview(){const s=routeStatus();return `<section class="side-section"><div class="eyebrow">HYPOTHETICAL OPERATIONS</div><h2 class="scenario-name">先确认路径，再进入现场。</h2><span class="tag orange">全部为假设资源</span><p class="description">源道路中心线上生成候选巡查路线，按时序水深执行 0.30 m 停止规则。</p>${!isSurface()?'<div class="note-box orange">历史窗口没有真实救援轨迹。请切换河道外洪查看假设任务。</div><button id="show-surface" class="focus-btn">查看河道外洪情景 →</button>':`<div class="metric-grid"><div><span class="label">任务状态</span><strong style="font-size:17px" id="task-status">${s.status}</strong></div><div><span class="label">行驶里程</span><strong class="mono"><span id="task-distance">${fmt(s.distance/1000,2)}</span><small>km</small></strong></div></div>`}</section>`}
function logSection(){const logs=emergency?.logs.filter(l=>l.t<=state.time)||[];return `<section class="side-section"><div class="section-title"><h2>情景行动日志</h2><small>${isSurface()?logs.length:0} 条</small></div>${!isSurface()?'<div class="empty">此历史窗口无真实行动日志。</div>':logs.map(l=>`<button class="event-row" data-event="${l.t}"><span class="event-dot"></span><span class="event-text">${l.text}</span><time class="mono">${clock(l.t)}</time></button>`).join('')||'<div class="empty">尚未到达计划出发时刻。</div>'}</section>`}
function renderSidebar(){
 sidebarMemory.capture($('#sidebar'));
 let content='';if(state.tab==='sources')content=sources();else if(state.workspace==='response')content=assemblyNavigation(plans[state.scenario].shelters,state.selected,ico)+(selected().kind==='assembly'?inspector():'')+missionPanel(missions,currentMission(),selected(),state.workspace,t=>isSurface()?clock(t):clock(t+16200),ico);else if(state.workspace==='drones')content=missionPanel(missions,currentMission(),selected(),state.workspace,t=>isSurface()?clock(t):clock(t+16200),ico);else if(state.workspace==='evacuation')content=evacPanel(state,plans[state.scenario],currentOps(),selected(),ico,()=>inspector());else if(state.workspace==='response')content=responseOverview()+objectsSection()+(selected().kind==='resource'?inspector():'')+logSection();else if(state.tab==='objects')content=selected().kind==='building'?inspector()+objectsSection()+eventsSection():objectsSection()+inspector()+eventsSection();else content=overview()+layerSection()+inspector()+eventsSection();
 $('#sidebar').innerHTML=`<div class="side-tabs"><button class="side-tab ${state.tab==='layers'?'active':''}" data-tab="layers">总览图层</button><button class="side-tab ${state.tab==='objects'?'active':''}" data-tab="objects">对象检查</button><button class="side-tab ${state.tab==='sources'?'active':''}" data-tab="sources">来源</button></div>${content}`;
 $$('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderSidebar()});
 $$('[data-layer]').forEach(c=>c.onchange=()=>{state.layers[c.dataset.layer]=c.checked;applyLayers()});
 if($('#particle-density'))$('#particle-density').oninput=e=>{state.particleDensity=+e.target.value;scene.setParticleDensity(state.particleDensity);$('#density-value').textContent=state.particleDensity};
 $$('[data-opacity]').forEach(c=>c.oninput=()=>{const id=c.dataset.opacity;state.opacities[id]=c.value/100;scene.setOpacity(id,c.value/100)});
 $$('[data-object]').filter(b=>!b.closest('#assembly-onsite')).forEach(b=>b.onclick=()=>select(b.dataset.object,true));if($('#assembly-onsite'))$('#assembly-onsite').onclick=e=>{const b=e.target.closest('[data-object]');if(b)select(b.dataset.object,true)};
 $$('[data-event]').forEach(b=>b.onclick=()=>setTime(+b.dataset.event,true));
 bindMissionActions();if($('#focus-selected'))$('#focus-selected').onclick=()=>scene.focus(selected().xy,['patrol','evacuee'].includes(selected().kind)?120:selected().kind==='building'?280:330);
 if($('#show-history'))$('#show-history').onclick=()=>{setScenario('history');select('G71F04R',true)};
 if($('#show-surface'))$('#show-surface').onclick=()=>setScenario('surface');
 if($('#details'))$('#details').onclick=help;
 if($('#guidance-event'))$('#guidance-event').onclick=()=>{const a=plans[state.scenario].agents.find(a=>a.guidedBy);if(a){setTime(a.guidanceTime,true);select(a.id,true);scene.followXY=()=>objects[a.id].xy}};if($('#follow-group'))$('#follow-group').onclick=()=>{const a=currentOps().groups.find(a=>a.status===1)||currentOps().groups[0];select(a.id,true);scene.followXY=()=>objects[a.id].xy};if($('#follow-patrol'))$('#follow-patrol').onclick=()=>{select('T01',true);scene.followXY=()=>objects.T01.xy};if($('#evac-camera'))$('#evac-camera').onclick=()=>scene.focus([150,120],1000);refreshIcons();updateEvacReadings();sidebarMemory.restore($('#sidebar'),state.workspace+':'+state.tab);
}
function setWorkspace(value){
 scene.followXY=null;scene.followTarget=null;state.workspace=value;state.tab=value==='incident'?'layers':'objects';if(value!=='drones')scene.flightCamera.close();
 if(value==='drones'&&!missions.drones.some(d=>d.id===state.selected))state.selected='D01';
 else if(value==='response'&&!missions.resources.some(d=>d.id===state.selected&&d.type!=='depot')&&!plans[state.scenario].shelters.some(d=>d.id===state.selected))state.selected='A01';
 else if(value==='evacuation'&&!['assembly','evacuee','patrol'].includes(selected().kind))state.selected='A01';
 else if(value==='monitor'&&!history.sensors[state.selected])state.selected='G71F04R';
 else if(value==='incident'&&(missionKind(selected())||['assembly','evacuee','patrol','resource'].includes(selected().kind)))state.selected=isSurface()?'P02':'P04';
 scene.missionView.setWorkspace(value);scene.setTime(state.time);updateOperationLocations();updateMissionLocations();scene.select(state.selected,selected().xy);renderAll();applyLayers();if(value==='drones')scene.focus([100,260],1600);toast(WORKSPACES[value]);
}
async function setScenario(value){
 if(value===state.scenario)return;const token=++switchToken;state.playing=false;renderTransport();const old=state.scenario;$('#scenario').disabled=true;toast('正在加载情景结果…');
 try{const pack=await scenarioStore.load(value);if(token!==switchToken)return;scenarioStore.activate(value,pack);scene.followXY=null;scene.followTarget=null;scene.flightCamera.close();state.savedTimes[old]=state.time;state.scenario=value;surface=pack.model;missions=pack.mission;models={...modelHeaders,[value]:surface};state.time=state.savedTimes[value];$('#scenario').value=value;scene.setModel(surface);scene.setOperations(plans[value]);scene.missionView.setPlan(missions);for(const o of Object.values(objects))delete o.depthSeries;missionSeriesCache.clear();updateOperationalObjects();registerMissions();state.selected=state.workspace==='drones'?'D01':state.workspace==='response'?'A01':state.workspace==='evacuation'?'A01':state.workspace==='monitor'?'G71F04R':isSurface()?'P02':'P04';setTime(state.time);scene.select(state.selected,selected().xy);renderAll();applyLayers();if(!isSurface()&&state.workspace==='incident')scene.focus(surface.viewpoints.ponding,380);toast(isSurface()?'假设外洪 + 假设降雨':'历史雨量实测，水深为地表试算');}
 catch(e){$('#scenario').value=old;toast(e.message+'；当前情景已保留，可重新选择重试');console.warn('Scenario load:',e.message)}finally{if(token===switchToken)$('#scenario').disabled=false}
}
function beginResourceFollow(id){
 const r=missions.resources.find(r=>r.id===id);if(!r||r.type==='depot')return false;
 scene.flightCamera.close();scene.followXY=null;scene.followTarget=null;
 if(r.sharedPatrol){scene.focus(objects[id].xy,85);scene.followXY=()=>scene.operationsView.current?.patrols.find(p=>p.id===id)?.xy??objects[id].xy}
 else{scene.focusObject(id,r.type==='helicopter'?90:r.type==='boat'?75:r.type==='crew'?75:70);scene.followTarget=()=>scene.missionView.worldPosition(id)}
 return true;
}
function select(id,focus=false){
 if(!objects[id])return;if(missions.resources.find(r=>r.id===id)?.type==='depot'){const station=currentAssemblies().find(s=>s.depots.includes(id));if(station)id=station.id}
 scene.followXY=null;scene.followTarget=null;state.selected=id;const o=objects[id];
 if(['building','assembly','evacuee','patrol','drone','mission-resource'].includes(o.kind))state.tab='objects';scene.select(id,o.xy);
 if(o.kind==='drone'&&scene.flightCamera.state.open)scene.flightCamera.open(id,scene.flightCamera.state.full);
 const autoFollow=focus&&state.workspace==='response'&&beginResourceFollow(id);
 if(focus&&!autoFollow){if(scene.missionView.models.has(id))scene.focusObject(id,o.kind==='drone'?420:100);else scene.focus(o.xy,['patrol','evacuee'].includes(o.kind)?120:o.kind==='building'?280:330)}
 renderSidebar();renderCharts();renderLabels();
}

function setTime(t,pause=false){state.time=Math.max(0,Math.min(duration(),t));if(pause)state.playing=false;scene.setTime(state.time);scene.operationsView.setTime(state.time);scene.rainView.setRate(rainAt(surface,state.time));updateOperationLocations();updateMissionLocations();renderTime();renderCharts();updateReadings();renderContext();if(pause){renderSidebar();renderTransport()}}
function jump(dir){const ev=isSurface()?surfaceEvents:historyEvents;const e=dir>0?ev.find(e=>e.t>state.time+1):[...ev].reverse().find(e=>e.t<state.time-1);setTime(e?.t??(dir>0?duration():0),true)}
function renderTransport(){$('#play').innerHTML=ico(state.playing?'Pause':'Play');$('#play').title=state.playing?'暂停回放':'播放回放';refreshIcons()}
function renderTime(){
 const phases=isSurface()?[[1200,'来水'],[3600,'深淹'],[6600,'退水']]:[[6360,'最强降雨'],[9000,'雨后积水'],[21600,'窗口末']];$$('[data-phase]').forEach((b,i)=>{b.dataset.phase=phases[i][0];b.textContent=phases[i][1]});
 const d=duration(),t=state.time;$('#timeline').max=d;$('#timeline').value=t;$('#timeline').style.setProperty('--progress',`${t/d*100}%`);$('#time-readout').textContent=timeText();$$('[data-phase]').forEach(b=>b.classList.toggle('active',Math.abs(state.time-Number(b.dataset.phase))<480));$('#time-kind').textContent=isSurface()?'假设雨洪':'历史雨量 · 模拟积水';$('#time-kind').className=`tag ${isSurface()?'orange':'blue'}`;
 $('#timeline-context').textContent=isSurface()?'COMPOUND RAIN / 120 MIN':'HISTORICAL RAIN / 6 H';$('#ticks').innerHTML=(isSurface()?['00:00','00:20','00:40','01:00','01:20','01:40','02:00']:['04:30','05:30','06:30','07:30','08:30','09:30','10:30']).map(v=>`<span class="mono">${v}</span>`).join('');$('#end-time').textContent=isSurface()?'02:00':'10:30';$('#event-markers').innerHTML=(isSurface()?surfaceEvents:historyEvents).map(e=>`<i style="left:${e.t/d*100}%"></i>`).join('');
}
