 const elements=$$('[data-marker]'),items=elements.map(el=>{const o=objects[el.dataset.marker],p=scene.projectObject(o.id,o.xy,16);return{id:o.id,x:p.x,y:p.y,width:el.offsetWidth||100,height:el.offsetHeight||25,selected:o.id===state.selected,visible:p.visible&&state.layers.sensors&&(o.kind!=='assembly'||state.layers.assembly)&&!(p.x<430&&p.y<190&&o.id!==state.selected)}});
