function showModal(content){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><button class="close" aria-label="关闭">${ico('X')}</button>${content}</div></div>`;$('.modal .close').onclick=()=>$('#modal-root').innerHTML='';$('.modal-backdrop').onclick=e=>{if(e.target===$('.modal-backdrop'))$('#modal-root').innerHTML=''};refreshIcons()}
function help(){showModal(`<span class="eyebrow">FLOODTRACE v0.4</span><h2>雨洪、侦察与应急行动。</h2><ol><li>顶部路线图标打开26段完整演示导览，可逐段选择或按参考节奏自动浏览。手动切换工作空间或拖动时间会结束导览。</li><li>「灾情推演」观察两组真实计算的地表水面；历史实测指雨量和监测记录，水深为模型结果。历史「街区近景」定位积水洼地。</li><li>「无人机」选择六种模拟任务，打开侦察相机。EO来自同一三维场景；水深和风险为模型分析。云台、变焦、两种色板与全屏均可操作，模型记录可定位到发生时刻和地点。</li><li>「应急处置」查看十三个示意资源，选择移动单位随行。装载、投送、返程、补给及道路受阻与余量、图表、日志联动。投送不改变水动力。</li><li>「疏散与安全」显示360名群众、三处集结点和三队巡检。可跟看人员或定位引导交接。巡检六人与资源工作空间共享，其余行动人员另计。</li><li>暂停固定水情、累计量和任务；雨滴与水纹可继续视觉相位。1×回放每秒推进60模型秒，0.25×适合近景。强降雨密度限幅，可关闭或调淡。</li><li>左键旋转、右键平移、滚轮缩放；空格播放/暂停，Home全景，Esc关闭相机或导览。拖动地图结束随行。</li></ol><div class="note-box orange">无人机、资源、人口、容量和安全阈值为示意。绿色为满足本次模型规则的候选区；灰色未评估。两组计算无入渗、无排水，历史河道边界是假设，ANUGA与SWMM尚未耦合。</div>`)}
function exportSnapshot(){const o=selected(),payload={product:'FloodTrace MVP',exportedAt:new Date().toISOString(),scenario:state.scenario,modelId:surface.id,workspace:state.workspace,time:state.time,timeText:timeText(),selected:{id:o.id,kind:o.kind,xy:o.xy,count:o.count,capacity:o.capacity},rainMmH:rainAt(surface,state.time),rainCumulativeMm:at(surface.rainCumulative,state.time),rainGauge:surface.rainGauge,operations:state.workspace==='evacuation'?{...currentOps(),assumptions:plans[state.scenario].assumptions}:null,layers:state.layers,mission:currentMission(),displayContext:scene.waterContext.stats,assembly:selected().kind==='assembly'?currentAssemblies().find(s=>s.id===state.selected):null,camera:scene.flightCamera.snapshot(),coordinates:{crs:data.crs,origin:data.origin,axes:['east','south'],unit:'m',verticalDatum:data.verticalDatum},units:{depth:'m',stage:'m DVR90',agl:'m above terrain',speed:'m/s',heading:'degrees clockwise from north',battery:'%',link:'dBm',payload:'illustrative boxes',rainMmH:'mm/h'},view:state.mode,displayVerticalExaggeration:state.exag,resultVersion:'v0.4.3',value:at(seriesAtObject(),state.time),unit:networkEvidence()&&['sensor','node'].includes(o.kind)?'m DVR90 network head':'m simulated surface depth',kind:surface.kind,coupled:false,assumptions:surface.assumptions,source:'https://doi.org/10.11583/DTU.c.5029124'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`FloodTrace-${state.scenario}-${Math.floor(state.time)}s.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前分析快照 JSON')}
