function updateMissionReadings(){if(!missions||!['drones','response'].includes(state.workspace))return;const s=currentMission(),q=[...s.drones,...s.resources].find(r=>r.id===state.selected);$$('[data-mission-status]').forEach(el=>{const o=[...s.drones,...s.resources].find(r=>r.id===el.dataset.missionStatus);if(o)el.textContent=MISSION_STATUS[o.status]});$$('[data-mission-reading]').forEach(el=>{const o=[...s.drones,...s.resources].find(r=>r.id===el.dataset.missionReading);if(o)el.textContent=Number.isFinite(o.battery)?o.battery.toFixed(0)+'%':o.capacity?o.payload.toFixed(0)+'箱':el.textContent});if(q){const vals={altitude:q.agl,speed:q.speed,heading:q.heading,battery:q.battery,link:q.link,payload:q.payload,delivered:q.delivered,crew:q.crew};$$('[data-telemetry]').forEach(el=>{const k=el.dataset.telemetry;el.textContent=k==='elapsed'?clock(state.time):Number.isFinite(vals[k])?vals[k].toFixed(['speed','altitude','battery'].includes(k)?1:0):'—'});if($('#mission-current-status'))$('#mission-current-status').textContent=MISSION_STATUS[q.status];if($('#mission-position'))$('#mission-position').textContent=q.xy.map(a=>a.toFixed(1)).join(' / ')+' m'}const logs=state.workspace==='drones'?s.detections:s.events;const key=state.workspace+':'+logs.length+':'+logs.filter(e=>e.completed).length;if($('#mission-log')&&$('#mission-log').dataset.key!==key){$('#mission-log').dataset.key=key;$('#mission-log').innerHTML=missionLogs(logs,state.workspace==='drones',t=>isSurface()?clock(t):clock(t+16200));if($('#mission-log-count'))$('#mission-log-count').textContent=logs.length+' 条'}$$('[data-mission-total]').forEach(el=>el.textContent=s.totals[el.dataset.missionTotal].toFixed(0));$$('[data-fleet-value]').forEach(el=>{const k=el.dataset.fleetValue;el.textContent=k==='battery'?(s.drones.reduce((a,d)=>a+d.battery,0)/6).toFixed(0)+'%':k==='detections'?s.detections.length:s.totals.active});}
function renderContext(){if(!scene)return;let title='关键事件',items=(isSurface()?surfaceEvents:historyEvents).map(e=>({t:e.t,label:e.name}));if(state.workspace==='drones'){title='模型采样记录';items=currentMission().detections.slice(-6).reverse().map(e=>({t:e.t,label:e.droneId+' · '+e.depth.toFixed(2)+' m',id:e.droneId}))}else if(state.workspace==='response'){title='行动日志';items=currentMission().events.slice(-6).reverse().map(e=>({t:e.until??e.t,label:e.resourceId+' · '+({load:'装载',reload:'补给',deliver:'物资投送',blocked:'道路受阻',support:'到达支援点'}[e.kind]),id:e.resourceId}))}else if(state.workspace==='evacuation'){title='人员与巡检';items=plans[state.scenario].logs.filter(e=>e.t<=state.time).slice(-6).reverse().map(e=>({t:e.t,label:e.text}))}$('#context-panel').innerHTML=`<h3>${title}<small>${items.length} 条</small></h3>${items.slice(0,6).map(e=>`<button data-context-time="${e.t}" ${e.id?`data-context-object="${e.id}"`:''}><i></i><span>${e.label}</span><time>${isSurface()?clock(e.t):clock(e.t+16200)}</time></button>`).join('')||'<p>等待模型时刻进入任务窗口</p>'}`;}
let tourTimer=null,tourIndex=0,tourAuto=false;
function openTour(){stopTour();showModal(`<h2>完整演示导览</h2><p>26段参考流程已适配洪涝场景。点击单段检查，或按参考节奏自动浏览。当前情景：${isSurface()?'假设外洪 + 降雨':'历史降雨 → 模拟积水'}。</p><button class="focus-btn" id="tour-start">自动浏览完整演示 · 约115秒</button><div class="tour-step-list">${REFERENCE_STEPS.map(a=>`<button data-tour-step="${a.index}"><time>${a.ref}</time><span>${a.index+1}. ${a.title}</span></button>`).join('')}</div>`);$$('[data-tour-step]').forEach(b=>b.onclick=()=>{stopTour();runTourStep(+b.dataset.tourStep)});$('#tour-start').onclick=()=>{tourAuto=true;runTourStep(0)}}
function stopTour(){const wasAuto=tourAuto;clearTimeout(tourTimer);tourAuto=false;document.querySelector('.tour-player')?.remove();if(wasAuto&&scene){state.playing=false;scene.controls.autoRotate=false;renderTransport()}}
function runTourStep(i){if(i>=REFERENCE_STEPS.length){stopTour();toast('完整演示已结束');return}tourIndex=i;const a=REFERENCE_STEPS[i];$('#modal-root').innerHTML='';scene.flightCamera.close();setWorkspace(a.workspace);state.mode=a.mode;scene.setMode(a.mode);$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===a.mode));let t=duration()*a.fraction;if(a.action==='delivery'){const e=missions.events.find(e=>e.resourceId===a.id&&e.kind==='deliver');if(e)t=(e.t+e.until)/2}if(a.action==='reload'){const e=missions.events.find(e=>e.resourceId===a.id&&e.kind==='reload');if(e)t=(e.t+e.until)/2}if(a.action==='guidance'){const e=plans[state.scenario].agents.find(a=>a.guidedBy);if(e){t=e.guidanceTime;a.guidedGroup=e.id}}setTime(t,true);select(a.id,true);if(['overview','district','inflow'].includes(a.action))scene.viewPreset(a.action);if(a.action==='fleet')scene.focus([80,180],1600);if(['eo','depth','full','whitehot'].includes(a.action)){scene.flightCamera.open(a.id,['full','whitehot'].includes(a.action));scene.flightCamera.state.mode=a.action==='eo'?'eo':'depth';scene.flightCamera.state.palette=a.action==='whitehot'?'whitehot':'ironbow';scene.flightCamera.updateControls()}if(a.action==='follow'||a.action==='delivery'||a.action==='reload')followResource(a.id);if(a.action==='guidance'&&a.guidedGroup){select(a.guidedGroup,true);scene.followXY=()=>objects[a.guidedGroup].xy}if(a.action==='flow'){state.layers.flow=true;state.layers.vectors=true;applyLayers();scene.overview();scene.controls.autoRotate=true}let player=document.querySelector('.tour-player');if(!player){player=document.createElement('div');player.className='tour-player';$('.map-panel').appendChild(player)}player.innerHTML=`<span>${i+1} / 26</span><b>${a.title}</b><button id="tour-prev" aria-label="上一个演示片段">‹</button><button id="tour-pause">${tourAuto?'暂停导览':'继续导览'}</button><button id="tour-next" aria-label="下一个演示片段">›</button><button id="tour-close" aria-label="结束演示导览">×</button>`;$('#tour-prev').onclick=()=>{clearTimeout(tourTimer);runTourStep(Math.max(0,tourIndex-1))};$('#tour-next').onclick=()=>{clearTimeout(tourTimer);runTourStep(tourIndex+1)};$('#tour-close').onclick=stopTour;$('#tour-pause').onclick=()=>{tourAuto=!tourAuto;clearTimeout(tourTimer);if(tourAuto)runTourStep(tourIndex);else{state.playing=false;renderTransport();$('#tour-pause').textContent='继续导览'}};if(tourAuto){state.speed=.25;$('#speed').value='0.25';state.playing=state.time<duration();renderTransport();const match=a.ref.match(/(\d+):(\d+)–(\d+):(\d+)/);const seconds=match?+match[3]*60+ +match[4]-(+match[1]*60+ +match[2]):4;tourTimer=setTimeout(()=>runTourStep(i+1),seconds*1000)}}

async function init(){shell();try{
 const [c,pack,h,a,b,e,hm]=await Promise.all([fetch(assetUrl('/data/city.json')).then(r=>r.json()),scenarioStore.load('surface'),fetch(assetUrl('/data/history.json')).then(r=>r.json()),loadOperations('/data/compound-operations.json'),loadOperations('/data/historical-operations.json'),fetch(assetUrl('/data/compound-emergency.json')).then(r=>r.json()),fetch(assetUrl('/data/historical.json')).then(r=>r.json())]);
 data=c;surface=pack.model;missions=pack.mission;modelHeaders={surface:JSON.parse(JSON.stringify(surface,(k,v)=>['fields','depth','ground','buildingMask'].includes(k)?undefined:v)),history:hm};models={...modelHeaders,surface};scenarioStore.activate('surface',pack);history=h;plans={surface:a,history:b};emergency=e;scene=new FloodScene($('#scene'),data,surface,id=>select(id,true),hover);scene.getPhysicalTime=()=>state.time;scene.setOperations(a);scene.missionView.setPlan(missions);makeObjects();updateOperationalObjects();registerMissions();scene.addMarker('P04',objects.P04.xy,'checkpoint');scene.select(state.selected,selected().xy);scene.onRender=positionLabels;setTime(state.time);renderAll();applyLayers();$('.loading').remove();$('.shell').setAttribute('aria-busy','false');$$('.shell button,.shell select,.shell input').forEach(el=>el.disabled=false);
 window.floodTrace={state,scene,data,get models(){return models},modelHeaders,plans,history,emergency,get missions(){return missions},getAssemblies:currentAssemblies,setWorkspace,setTime,select,setScenario,getSnapshot:()=>({time:state.time,playing:state.playing,selected:state.selected,scenario:state.scenario,workspace:state.workspace,mode:state.mode,modelId:surface.id,value:at(seriesAtObject(),state.time),waterCellCount:surface.nativeCells,rain:{inputMmH:rainAt(surface,state.time),cumulativeMm:at(surface.rainCumulative,state.time),gauge:surface.rainGauge,visual:scene.rainView.stats},operations:currentOps(),mission:currentMission(),camera:scene.flightCamera.snapshot(),tracers:scene.waterView.stats,displayContext:scene.waterContext.stats,building:selected().kind==='building'?scene.buildingReading(selected().sourceIndex):null,render:scene.renderer.info.render})};requestAnimationFrame(tick)
 }catch(e){console.error(e);$('.shell').setAttribute('aria-busy','false');$('.loading').innerHTML=`<span>${e.message}。<button id="retry-load">重新加载</button></span>`;$('#retry-load').onclick=()=>location.reload()}}
function tick(now){requestAnimationFrame(tick);const dt=lastTick?Math.min((now-lastTick)/1000,.3):0;lastTick=now;if(state.playing){state.time=Math.min(duration(),state.time+dt*60*state.speed);if(now-uiTick>80){setTime(state.time);uiTick=now}if(state.time>=duration()){state.playing=false;renderTransport();renderSidebar()}}}
init();
